CREATE TABLE employee_terms(id INTEGER PRIMARY KEY,employee_id INTEGER NOT NULL REFERENCES employees(id),previous_id INTEGER REFERENCES employee_terms(id),effective_date TEXT NOT NULL,terms_encrypted TEXT NOT NULL,reason TEXT NOT NULL,creator_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE employee_term_approvals(term_id INTEGER PRIMARY KEY REFERENCES employee_terms(id),actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE leave_pay_classifications(request_id INTEGER PRIMARY KEY REFERENCES leave_requests(id),paid INTEGER NOT NULL CHECK(paid IN(0,1)),actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE warehouses(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id));
CREATE TABLE stock_documents(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),kind TEXT NOT NULL CHECK(kind IN('receipt','issue','transfer','count','return','reversal')),reference TEXT NOT NULL UNIQUE,date TEXT NOT NULL,reason TEXT NOT NULL,recipient TEXT NOT NULL DEFAULT '',creator_id INTEGER NOT NULL REFERENCES users(id),approval_policy TEXT NOT NULL,reversal_of INTEGER UNIQUE REFERENCES stock_documents(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE stock_document_lines(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES stock_documents(id),warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),to_warehouse_id INTEGER REFERENCES warehouses(id),item_id INTEGER NOT NULL REFERENCES items(id),bill_line_id INTEGER REFERENCES bill_lines(id),lot_id INTEGER REFERENCES stock_document_lines(id),quantity INTEGER NOT NULL CHECK(quantity<>0),amount INTEGER NOT NULL CHECK(amount>0),expected_quantity INTEGER,expected_amount INTEGER,source_id INTEGER NOT NULL REFERENCES funding_sources(id));
CREATE TABLE stock_posts(document_id INTEGER PRIMARY KEY REFERENCES stock_documents(id),journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id));
CREATE TABLE stock_cancellations(document_id INTEGER PRIMARY KEY REFERENCES stock_documents(id),actor_id INTEGER NOT NULL REFERENCES users(id),reason TEXT NOT NULL);
CREATE TABLE stock_movements(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES stock_documents(id),lot_id INTEGER NOT NULL REFERENCES stock_document_lines(id),warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),quantity INTEGER NOT NULL CHECK(quantity<>0),amount INTEGER NOT NULL CHECK(amount<>0),date TEXT NOT NULL);
CREATE INDEX stock_position ON stock_movements(lot_id,warehouse_id,date);
INSERT INTO accounts(code,name,type) VALUES('1400','Warehouse inventory','asset'),('5300','Inventory count variance','expense');
